function beautifulSubsets(nums, k) {
  const count = new Map();
  let total = 0;

  const explore = (index) => {
    if (index === nums.length) {
      total++;
      return;
    }
    explore(index + 1);
    const value = nums[index];
    const lowerTaken = (count.get(value - k) ?? 0) > 0;
    const upperTaken = (count.get(value + k) ?? 0) > 0;
    if (!lowerTaken && !upperTaken) {
      count.set(value, (count.get(value) ?? 0) + 1);
      explore(index + 1);
      count.set(value, count.get(value) - 1);
    }
  };

  explore(0);
  return total - 1;
}

