function beautifulSubsets(nums, k) {
  const n = nums.length;
  let answer = 0;
  for (let mask = 1; mask < (1 << n); mask++) {
    let ok = true;
    for (let i = 0; i < n && ok; i++) {
      if (!(mask & (1 << i))) continue;
      for (let j = i + 1; j < n; j++) {
        if ((mask & (1 << j)) && Math.abs(nums[i] - nums[j]) === k) { ok = false; break; }
      }
    }
    if (ok) answer++;
  }
  return answer;
}

