function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const k = pick(1, 4);
    const top = pick(3, 15);
    const nums = Array.from({ length: n }, () => pick(1, top));
    return [nums, k];
  }
  const n = 18;
  const style = pick(0, 2);
  if (style === 0) {
    const k = pick(1, 1000);
    return [Array.from({ length: n }, () => pick(1, 1000)), k];
  }
  // Many values on a few arithmetic chains with step k, so conflicts are frequent.
  const k = pick(1, 50);
  const starts = Array.from({ length: pick(1, 3) }, () => pick(1, 50));
  const nums = Array.from({ length: n }, () => {
    const start = starts[pick(0, starts.length - 1)];
    return Math.min(1000, start + k * pick(0, 6));
  });
  return [nums, k];
}
